package com.example.takura.communications;
import static org.assertj.core.api.Assertions.*;import com.example.takura.communications.application.*;import com.example.takura.quotations.application.QuoteSecretProtector;import com.fasterxml.jackson.databind.ObjectMapper;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class OutboxReliabilityPostgresqlTest{@Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:17.11-alpine3.24");static JdbcTemplate jdbc;static TransactionTemplate tx;Instant now=Instant.parse("2026-10-21T08:00:00Z");UUID enquiry;@BeforeAll static void migrate(){var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());Flyway.configure().dataSource(ds).locations("classpath:db/migration").defaultSchema("takura").schemas("takura").load().migrate();jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}@BeforeEach void setup(){jdbc.execute("TRUNCATE takura.notification_outbox,takura.enquiry CASCADE");enquiry=UUID.randomUUID();jdbc.update("INSERT INTO takura.enquiry(id,reference,state,team_code,full_name,email,preferred_contact,country_code,town_or_suburb,description,privacy_notice_version,privacy_acknowledged_at,created_at) VALUES(?,?,'NEW','GENERAL','Synthetic','sink@example.invalid','EMAIL','ZA','Area','Safe fixture','v1',?,?)",enquiry,"OUT-"+enquiry.toString().substring(0,8),Timestamp.from(now),Timestamp.from(now));}
 @Test void ambiguousTimeoutIsVisibleAndNeverBlindlyRetried(){UUID event=event("unknown");OutboxWorker worker=worker((t,r)->{throw new DeliveryFailure(DeliveryFailure.Kind.UNKNOWN,"TIMEOUT_UNKNOWN",null);});assertThat(worker.runOnce()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT state FROM takura.notification_outbox WHERE id=?",String.class,event)).isEqualTo("DELIVERY_UNKNOWN");assertThat(jdbc.queryForObject("SELECT possibly_accepted FROM takura.notification_outbox WHERE id=?",Boolean.class,event)).isTrue();assertThat(worker.runOnce()).isZero();}
 @Test void permanentFailureStopsImmediately(){UUID event=event("permanent");OutboxWorker worker=worker((t,r)->{throw new DeliveryFailure(DeliveryFailure.Kind.PERMANENT,"ADDRESS_REJECTED",null);});worker.runOnce();assertThat(jdbc.queryForObject("SELECT state FROM takura.notification_outbox WHERE id=?",String.class,event)).isEqualTo("FAILED_REQUIRES_REVIEW");assertThat(jdbc.queryForObject("SELECT attempts FROM takura.notification_outbox WHERE id=?",Integer.class,event)).isEqualTo(1);}
 private UUID event(String key){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO takura.notification_outbox(id,event_type,aggregate_id,semantic_key,payload,next_attempt_at,created_at,originating_correlation_id,originating_trace_id) VALUES(?,'TEST',?,?,?::jsonb,?,?,?,?)",id,enquiry,key,"{\"template\":\"test\",\"recipient\":\"sink@example.invalid\"}",Timestamp.from(now),Timestamp.from(now),"corr-safe","trace-safe");return id;}private OutboxWorker worker(CommunicationPort port){String key=Base64.getEncoder().encodeToString("0123456789abcdef0123456789abcdef".getBytes());return new OutboxWorker(jdbc,tx,port,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC),new QuoteSecretProtector(key));}}
